window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/natureza_2024.js"]=[{"title":"Deformar para dissipar energia","steps":["Na colisão, a região deformável transforma energia cinética em energia interna e deformação.","Isso reduz a energia mecânica disponível para danos e pode ampliar o tempo de desaceleração.","B descreve essa absorção. No sistema isolado carro/ocupantes/muro, o momento total e a velocidade do centro de massa conservam-se."],"alternatives":{"A":"Acionar o airbag é outro mecanismo, não o papel da deformação estrutural.","B":"A deformação converte energia cinética em outras formas sem destruir energia total.","C":"O momento total de um sistema isolado não é consumido durante uma colisão.","D":"A região deformável não é simplesmente uma parede rígida protetora.","E":"Forças internas não mudam a velocidade do centro de massa do sistema isolado."},"takeaway":"Defina o sistema: carro sozinho e conjunto carro mais muro não são equivalentes.","key":"natureza:N375","area":"natureza","year":2024,"number":91,"answer":"B","subject":"Física","topic":"Mecânica: cinemática e dinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Somar semirreações com elétrons iguais","steps":["A oxidação libera oito elétrons; a redução consome quatro.","Multiplique a redução por dois: 8 H⁺ + 2 O₂ + 8 e⁻ → 4 H₂O.","Some e cancele elétrons, sete H⁺ e duas H₂O: CH₃COO⁻ + H⁺ + 2 O₂ → 2 CO₂ + 2 H₂O, C."],"alternatives":{"A":"A equação com apenas um O₂ não conserva os átomos e as cargas.","B":"Forma acetato a partir de CO₂, invertendo o destino do carbono indicado.","C":"Conserva átomos e carga após igualar e cancelar os elétrons corretamente.","D":"Produz oxigênio, quando a semirreação de redução fornecida o consome.","E":"A orientação e os coeficientes não correspondem à soma das equações dadas."},"takeaway":"Iguale os elétrons antes de somar; só depois cancele as espécies repetidas.","key":"natureza:N764","area":"natureza","year":2024,"number":92,"answer":"C","subject":"Química","topic":"Eletroquímica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Orgânico não significa saudável","steps":["A antiga concepção vitalista ligava os compostos à origem nos seres vivos.","A classificação atual se baseia principalmente em estruturas de carbono.","E é a melhor definição entre as alternativas; existem exceções entre os compostos de carbono, como CO₂ e carbonatos."],"alternatives":{"A":"Há compostos orgânicos tóxicos; benefício à saúde não é critério químico.","B":"Nem todo composto orgânico é facilmente biodegradável, como mostram certos polímeros.","C":"Ser formado a partir de CO₂ não é exigência dessa classificação.","D":"Ausência de agrotóxicos pertence a outro uso da palavra orgânico.","E":"O carbono é o elemento estruturante da classificação química apresentada."},"takeaway":"Diferencie o conceito científico de orgânico de seus usos comercial e cotidiano.","key":"natureza:N673","area":"natureza","year":2024,"number":93,"answer":"E","subject":"Química","topic":"Química orgânica: funções e propriedades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Localizar o hidrogênio ácido","steps":["A base de Brönsted-Lowry deve receber um próton.","A sulfonamida possui N–H que pode perder H⁺, formando ânion estabilizado pelo grupo sulfonila.","A espécie carregada interage melhor com a água: o grupo é sulfonamida, A."],"alternatives":{"A":"O N–H da sulfonamida é o sítio ácido adequado à desprotonação descrita.","B":"Os hidrogênios da metila não constituem o sítio relevante nesse tratamento.","C":"A fenila não oferece próton ácido comparável ao da sulfonamida nas condições dadas.","D":"O grupo nitro mostrado não contém o hidrogênio capturado pela base.","E":"O éter não apresenta O–H e não é o grupamento que cede o próton indicado."},"takeaway":"Em reação ácido-base, procure a ligação capaz de ceder H⁺, não apenas átomos eletronegativos.","key":"natureza:N796","area":"natureza","year":2024,"number":94,"answer":"A","subject":"Química","topic":"Equilíbrio químico e pH","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Compensar o desvio do centro de massa","steps":["A figura coloca o CM acima e à direita do centro geométrico.","Adicionar massa puxa o centro de massa na direção da adição.","A correção requer o lado oposto, abaixo e à esquerda: ponto 3, alternativa C."],"alternatives":{"A":"O ponto 1 reforça a componente superior do desequilíbrio.","B":"O ponto 2 desloca para a esquerda, mas não compensa o desvio para cima.","C":"O ponto 3 se opõe às componentes horizontal e vertical do deslocamento.","D":"O ponto 4 fica abaixo, porém à direita, sem compensar o desvio horizontal.","E":"O ponto 5 está do mesmo lado do deslocamento e tende a aumentá-lo."},"takeaway":"Compense as duas componentes do desbalanceamento, não apenas uma delas.","key":"natureza:N376","area":"natureza","year":2024,"number":96,"answer":"C","subject":"Física","topic":"Mecânica: cinemática e dinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Da massa do íon à massa do sal","steps":["Em 2 000 mL, há 1,4 × 2 000 = 2 800 mg = 2,8 g de sódio.","A massa de NaCl é 2,8 × 58,5/23 ≈ 7,12 g.","Divida pelas duas colheres pequenas: 3,56 g por colher, aproximadamente 3,6 g, D."],"alternatives":{"A":"0,7 g não fornece o sódio necessário segundo a proporção molar dada.","B":"1,8 g subestima a massa obtida ao converter sódio em NaCl.","C":"2,8 g é a massa total de sódio, não a massa de NaCl por colher.","D":"A conversão molar seguida da divisão em duas porções fornece cerca de 3,6 g.","E":"7,0 g aproxima a massa de sal das duas colheres juntas, não de uma só."},"takeaway":"Este é um cálculo de prova: diferencie concentração do íon e massa do composto.","key":"natureza:N742","area":"natureza","year":2024,"number":97,"answer":"D","subject":"Química","topic":"Soluções e concentração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Vitelo e nutrição dos descendentes","steps":["O cladograma relaciona monotremados, marsupiais e placentários.","Outras formas de aporte materno diminuem a dependência de reservas de vitelo; o leite alimenta os descendentes.","E é compatível. A lactação já ocorre em monotremados: não é exclusividade dos placentários, nem o diagrama representa uma escada de superioridade."],"alternatives":{"A":"O cladograma não demonstra aumento contínuo da quantidade de filhotes.","B":"Todos os grupos mostrados apresentam fecundação interna.","C":"Não aparece uma transição para reprodução exclusivamente sexuada entre esses grupos.","D":"Não se representa a passagem do desenvolvimento aquático para terrestre nesses mamíferos.","E":"A redução da dependência do vitelo se relaciona ao aporte materno e à lactação."},"takeaway":"Leia cladogramas como parentesco; características compartilhadas não surgem necessariamente no último ramo.","key":"natureza:N227","area":"natureza","year":2024,"number":98,"answer":"E","subject":"Biologia","topic":"Evolução e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Aproximação e aumento de frequência","steps":["A fonte sonora que se aproxima produz frequência percebida maior.","O som fica mais agudo, não mais forte por definição.","A reflexão na frente do veículo em aproximação também aumenta a frequência recebida pelo radar: fᵣ > f₀, D."],"alternatives":{"A":"A aproximação não reduz a frequência sonora nem a frequência de retorno.","B":"O som é mais agudo, mas a frequência refletida não diminui.","C":"O movimento do refletor impede tomar o retorno como frequência inalterada.","D":"A alternativa combina o aumento de frequência do som e do sinal refletido.","E":"O retorno tem maior frequência, mas o som não é percebido como mais grave."},"takeaway":"Agudo e grave tratam de frequência; forte e fraco tratam de intensidade.","key":"natureza:N454","area":"natureza","year":2024,"number":99,"answer":"D","subject":"Física","topic":"Ondulatória e acústica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Os raios realmente se encontram","steps":["Depois das duas reflexões, os raios se encontram na abertura superior.","A convergência efetiva caracteriza uma imagem real.","A separação vertical soma 3,8 + 3,8 = 7,6 cm, C; os 5 cm correspondem à largura da abertura."],"alternatives":{"A":"A imagem é real, mas 5 cm é uma dimensão horizontal da abertura.","B":"3,8 cm corresponde apenas a uma das duas parcelas verticais.","C":"O cruzamento real dos raios e a soma das alturas justificam real e 7,6 cm.","D":"A distância está correta, mas não se trata de imagem virtual.","E":"Além de errar a natureza da imagem, considera metade da distância vertical."},"takeaway":"Classifique a imagem pelo caminho dos raios e não pela impressão de um objeto flutuante.","key":"natureza:N542","area":"natureza","year":2024,"number":100,"answer":"C","subject":"Física","topic":"Óptica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A fala deve chegar a 50 dB","steps":["O ruído máximo é 45 dB e a diferença necessária é 5 dB.","Portanto, a curva da fala precisa estar em pelo menos 50 dB.","O gráfico chega a esse nível aproximadamente em 3 m, alternativa A; distâncias maiores não mantêm a margem."],"alternatives":{"A":"3,0 m é a leitura aproximada do limite de 50 dB na curva.","B":"Em 4,5 m, a curva já está abaixo dos 50 dB exigidos.","C":"6,5 m reduz ainda mais o nível e não respeita a margem requerida.","D":"8,0 m está na faixa de nível inferior ao mínimo calculado.","E":"9,5 m não mantém uma diferença de 5 dB sobre o ruído máximo."},"takeaway":"Converta o critério verbal em um limite numérico antes de ler o gráfico.","key":"natureza:N455","area":"natureza","year":2024,"number":101,"answer":"A","subject":"Física","topic":"Ondulatória e acústica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Calor e inativação enzimática","steps":["A transformação de glicose em amido depende de enzimas.","A água fervente altera a estrutura de parte dessas proteínas e reduz a atividade catalítica.","Preservar glicose e sabor doce decorre de desnaturação enzimática, A; a etapa fria limita o aquecimento posterior."],"alternatives":{"A":"A alteração da conformação pode inativar enzimas responsáveis pela transformação.","B":"Resfriar não explica uma conversão de nutrientes que preserve glicose pelo mecanismo descrito.","C":"A conservação do açúcar não é explicada por degradação geral das reservas.","D":"Bloquear a entrada de oxigênio não é o mecanismo enzimático indicado.","E":"O procedimento envolve imersão em água, não uma desidratação dos grãos."},"takeaway":"Enzimas dependem de estrutura: aquecimento intenso pode inativar em vez de acelerar a reação.","key":"natureza:N152","area":"natureza","year":2024,"number":102,"answer":"A","subject":"Biologia","topic":"Citologia e bioquímica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Transporte de calor entre coletor e reservatório","steps":["A pergunta não trata da energia que vai do Sol ao coletor.","A água aquecida circula até o reservatório, transportando energia, e a água mais fria retorna.","A movimentação do fluido caracteriza convecção, E; irradiação participa de outra etapa do sistema."],"alternatives":{"A":"Difusão molecular não é o mecanismo principal do transporte pela água que circula.","B":"Absorção nomeia o recebimento de energia, não o transporte entre os dois componentes.","C":"Condução pode existir nos materiais, mas não é o principal processo indicado.","D":"Irradiação explica a energia solar incidente, não o trajeto específico cobrado.","E":"A energia é transportada junto à circulação de água aquecida e fria."},"takeaway":"Um aquecedor pode envolver três mecanismos: identifique exatamente qual trecho está sendo perguntado.","key":"natureza:N496","area":"natureza","year":2024,"number":103,"answer":"E","subject":"Física","topic":"Termologia e termodinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Seguir a cadeia do fluxograma","steps":["A figura liga urbanização, ausência de saneamento e contaminação da água.","A etapa seguinte é a redução da biodiversidade aquática.","A perda de predadores de formas aquáticas dos mosquitos favorece os vetores e os riscos à saúde, D."],"alternatives":{"A":"Chikungunya e zika são arboviroses, não verminoses.","B":"A figura não apresenta eutrofização como o elo específico solicitado.","C":"Coliformes podem indicar contaminação, mas não explicam diretamente a cadeia das arboviroses.","D":"Menos predadores de larvas podem reduzir o controle biológico dos mosquitos.","E":"Proximidade de mosquitos é genérica e omite o mecanismo da perda de biodiversidade."},"takeaway":"Siga todas as setas: uma explicação geral pode ser verdadeira e ainda não ser a explicação da figura.","key":"natureza:N268","area":"natureza","year":2024,"number":104,"answer":"D","subject":"Biologia","topic":"Zoologia e parasitologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A afinidade por gordura orienta a acumulação","steps":["Os poluentes são descritos como apolares e lipossolúveis.","Essa característica favorece sua associação a compartimentos ricos em lipídios.","O tecido adiposo é a reserva lipídica mais diretamente relacionada à acumulação proposta: D."],"alternatives":{"A":"O tecido ósseo tem matriz mineral e não é a reserva lipídica pedida.","B":"Há lipídios no tecido nervoso, mas a alternativa não identifica o depósito adiposo preferencial.","C":"Epitélios não constituem a principal reserva corporal de gordura.","D":"Adipócitos acumulam gordura, favorecendo o depósito de substâncias lipossolúveis.","E":"O sangue é meio de transporte, não o reservatório preferencial indicado."},"takeaway":"Relacione propriedades da molécula à composição do tecido: lipossolúveis têm afinidade por lipídios.","key":"natureza:N006","area":"natureza","year":2024,"number":105,"answer":"D","subject":"Biologia","topic":"Ecologia e impactos ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Densidade e sobreposição na radiografia","steps":["A imagem depende das diferenças de transmissão e atenuação dos raios X.","Componentes densos do computador atenuam fortemente o feixe e escondem objetos sobrepostos.","Retirá-lo melhora a visualização: D. Não se trata de afirmar bloqueio absoluto de todo raio X por qualquer metal."],"alternatives":{"A":"A formação de sombras mostra que há interação com componentes densos.","B":"Não é um procedimento destinado a impedir desmagnetização por refração.","C":"O risco indicado não é aquecimento dos objetos por reflexão.","D":"A forte atenuação pelos componentes densos dificulta visualizar objetos sobrepostos.","E":"Ionização por difração não explica a necessidade de separar o computador."},"takeaway":"Em inspeção radiográfica, pense em atenuação e sobreposição, não em danos magnéticos ao equipamento.","key":"natureza:N608","area":"natureza","year":2024,"number":106,"answer":"D","subject":"Física","topic":"Física moderna e nuclear","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O reagente indica o órgão","steps":["A etapa inicial requer nitrito em contato com ácido clorídrico.","O suco gástrico contém HCl, fornecendo o meio ácido descrito.","Logo, o processo começa no estômago, E, antes das outras etapas citadas."],"alternatives":{"A":"O rim participa da excreção, mas não fornece o suco gástrico com HCl.","B":"O fígado metaboliza substâncias, mas não é o local do contato digestivo indicado.","C":"O intestino não é o ponto inicial caracterizado pela presença de HCl gástrico.","D":"O pâncreas não é o local onde o alimento encontra o ácido clorídrico.","E":"O estômago recebe o alimento e fornece o reagente ácido da reação inicial."},"takeaway":"Em questões de química e fisiologia, localize o reagente característico em cada órgão.","key":"natureza:N102","area":"natureza","year":2024,"number":107,"answer":"E","subject":"Biologia","topic":"Genética e biotecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Mudanças da comunidade ao longo do tempo","steps":["O SAF passa de culturas iniciais para uma comunidade com outras espécies e maior diversidade.","O texto trata de mudanças graduais de composição e estrutura, não de mudança genética de uma espécie.","O processo natural análogo é sucessão ecológica, B, embora aqui seja manejado."],"alternatives":{"A":"Rotação alterna cultivos, mas não define a transformação progressiva da comunidade apresentada.","B":"A substituição e incorporação de espécies ao longo do tempo caracterizam sucessão.","C":"Coevolução é mudança evolutiva recíproca entre espécies, não a sequência descrita.","D":"Seleção natural envolve diferenças hereditárias e reprodutivas, não apenas plantio e composição.","E":"Convergência é semelhança adaptativa entre linhagens, não o aumento da diversidade local."},"takeaway":"Distingua mudança na comunidade ecológica de mudança evolutiva nas populações.","key":"natureza:N007","area":"natureza","year":2024,"number":108,"answer":"B","subject":"Biologia","topic":"Ecologia e impactos ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Fibras rápidas favorecem esforço explosivo","steps":["As fibras brancas têm menos mitocôndrias e menor suprimento sanguíneo.","São adequadas a contrações rápidas e esforços intensos de curta duração, em vez de resistência prolongada.","O salto em altura exige potência e explosão: B. A proporção de fibras não determina sozinha todo o desempenho."],"alternatives":{"A":"Triatlo exige grande participação de metabolismo aeróbio e resistência prolongada.","B":"O salto requer uma ação breve e explosiva, favorecida por fibras rápidas.","C":"Marcha atlética é uma prova de resistência, não de explosão isolada.","D":"Maratona aquática depende de sustentar esforço por longo tempo.","E":"Ciclismo em estrada apresenta exigência importante de resistência aeróbia prolongada."},"takeaway":"Associe tipo de fibra ao padrão do esforço, sem transformar predisposição em destino esportivo.","key":"natureza:N191","area":"natureza","year":2024,"number":109,"answer":"B","subject":"Biologia","topic":"Fisiologia humana e saúde","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Parecer perigosa reduz o ataque","steps":["A falsa-coral não possui a defesa química da espécie peçonhenta.","Sua coloração semelhante pode levar predadores a evitá-la como evitariam a verdadeira.","A vantagem para a falsa é menor predação, D, num caso de mimetismo batesiano."],"alternatives":{"A":"A vantagem descrita está no comportamento do predador, não em facilitar captura de presas.","B":"As espécies não deixam de competir por recursos apenas por terem cores semelhantes.","C":"Semelhança de cores não garante compatibilidade reprodutiva nem híbridos.","D":"Imitar o sinal de uma espécie perigosa pode diminuir os ataques de predadores.","E":"A função indicada não é localizar parceiros para o acasalamento."},"takeaway":"Semelhança defensiva não é um método seguro de identificação de serpentes para manuseio.","key":"natureza:N228","area":"natureza","year":2024,"number":110,"answer":"D","subject":"Biologia","topic":"Evolução e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Crescer exige trocar o revestimento","steps":["O exoesqueleto rígido protege, mas não acompanha continuamente o aumento do corpo.","O animal realiza ecdise, eliminando o revestimento antigo e formando outro.","A substituição periódica por mudas permite o crescimento: D."],"alternatives":{"A":"Crustáceos jovens já têm exoesqueleto; ele não surge apenas na fase adulta.","B":"Fragmentar o revestimento nas articulações não é o mecanismo normal de crescimento.","C":"A rigidez impede o remodelamento contínuo sugerido pela alternativa.","D":"Mudas sucessivas possibilitam ampliar o corpo e depois endurecer um novo revestimento.","E":"A descrição não propõe tornar permanentemente distensível o revestimento por reduzir sais."},"takeaway":"Em artrópodes, diferencie crescimento corporal do aumento descontínuo das dimensões externas.","key":"natureza:N269","area":"natureza","year":2024,"number":111,"answer":"D","subject":"Biologia","topic":"Zoologia e parasitologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Quatro combinações no cruzamento ligado ao X","steps":["Use Xᴰ para visão não daltônica e Xᵈ para o alelo recessivo.","O pai XᴰY e a mãe XᴰXᵈ podem gerar XᴰXᴰ, XᴰXᵈ, XᴰY e XᵈY.","B reúne filha não portadora, filha portadora, filho não daltônico e filho daltônico. São possibilidades genéticas, não quatro nascimentos obrigatórios."],"alternatives":{"A":"Inclui filha daltônica, impossível com o Xᴰ recebido desse pai.","B":"Apresenta as quatro combinações possíveis para os gametas dos pais.","C":"Repete filhas portadoras e filhos não daltônicos, omitindo outros genótipos possíveis.","D":"Omite filhas portadoras e filhos não daltônicos, que também podem ocorrer.","E":"Inclui filhas daltônicas e exclui combinações possíveis para o casal dado."},"takeaway":"Monte os gametas e verifique a legenda antes de escolher um heredograma.","key":"natureza:N103","area":"natureza","year":2024,"number":112,"answer":"B","subject":"Biologia","topic":"Genética e biotecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Comparar processos de oxidação","steps":["Nitrificantes oxidam compostos nitrogenados, como amônio a nitrito e nitrato.","No ciclo do carbono, decompositores convertem carbono orgânico em CO₂, elevando sua oxidação.","A transformação redox análoga é a etapa 5, E, não as fixações de carbono ou nitrogênio."],"alternatives":{"A":"A fixação de N₂ em amônio envolve redução do nitrogênio.","B":"A desnitrificação de nitrato a N₂ é redução, oposta à nitrificação.","C":"A fixação fotossintética de CO₂ reduz o carbono, não o oxida.","D":"A fixação de CO₂ pelas plantas também envolve redução do carbono.","E":"A conversão de carbono orgânico em CO₂ é uma oxidação, como a nitrificação."},"takeaway":"Não compare só os nomes dos ciclos: acompanhe se o elemento ganha ou perde elétrons.","key":"natureza:N008","area":"natureza","year":2024,"number":113,"answer":"E","subject":"Biologia","topic":"Ecologia e impactos ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ler as curvas na razão igual a dezoito","steps":["Trace mentalmente uma vertical em ar/combustível = 18.","Nesse ponto, CO está próximo de zero, enquanto CO₂ permanece elevado.","A combinação correta é baixa emissão de CO e alta de CO₂, C; compare as curvas no ponto pedido, respeitando suas escalas."],"alternatives":{"A":"Com excesso de ar, O₂ já aumenta e NO não sustenta a combinação proposta.","B":"A curva de HC não está alta na condição pedida.","C":"CO está baixo e CO₂ ainda alto na leitura da razão dezoito.","D":"CO também está baixo, contrariando a segunda parte dessa alternativa.","E":"CO₂ não está baixo e HC não está alto nessa região do gráfico."},"takeaway":"Em gráficos com mais de uma escala, compare cada curva com seu eixo e com a abscissa solicitada.","key":"natureza:N622","area":"natureza","year":2024,"number":114,"answer":"C","subject":"Química","topic":"Química ambiental e separação de misturas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Actina sustenta forma e pseudópodes","steps":["O controle mantém a forma típica, enquanto a célula tratada fica arredondada e perde mobilidade.","A citocalasina B interfere em filamentos de actina do citoesqueleto.","Os microfilamentos, C, participam da forma e dos movimentos ameboides."],"alternatives":{"A":"Vacúolos podem participar de digestão ou equilíbrio osmótico, mas não são o alvo característico.","B":"Alterar energia poderia afetar movimentos, mas não é o alvo específico da citocalasina.","C":"Filamentos de actina sustentam projeções e rearranjos necessários aos pseudópodes.","D":"O experimento não aponta uma alteração direta do material genético.","E":"A membrana delimita a célula, mas o alvo descrito é a estrutura de actina associada à forma."},"takeaway":"Use o resultado do experimento junto ao mecanismo conhecido da droga, distinguindo membrana e citoesqueleto.","key":"natureza:N153","area":"natureza","year":2024,"number":115,"answer":"C","subject":"Biologia","topic":"Citologia e bioquímica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Separar o precipitado do líquido","steps":["A equação mostra Mg(OH)₂ no estado sólido e os demais componentes em solução.","O sólido pouco solúvel pode ser retido num filtro, enquanto a fase líquida o atravessa.","A técnica é filtração, A, preservando a separação do precipitado em relação aos solutos."],"alternatives":{"A":"O filtro retém o hidróxido precipitado e deixa passar a solução.","B":"Catação exige pedaços distinguíveis manipuláveis, não é adequada à suspensão fina.","C":"Destilar separa por volatilidade e não é a forma direta de recolher o precipitado.","D":"Dissolver o sólido eliminaria a condição que permite separá-lo fisicamente.","E":"Evaporar toda a água pode deixar também os sais dissolvidos junto ao sólido."},"takeaway":"Identifique primeiro os estados físicos: precipitado em líquido costuma permitir filtração.","key":"natureza:N623","area":"natureza","year":2024,"number":116,"answer":"A","subject":"Química","topic":"Química ambiental e separação de misturas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Vocalização tem função reprodutiva","steps":["O texto descreve anuros e um som repetido e intenso.","Nesses animais, a vocalização dos machos participa do reconhecimento e da atração de fêmeas.","A função mais diretamente associada é atrair parceiras para o acasalamento, E; a introdução em outra região não cria essa função."],"alternatives":{"A":"O canto não é um aviso deliberado de que o animal está fora do ambiente de origem.","B":"Não é um sinal específico de poluição urbana produzido pelo anuro.","C":"A intensidade do som não demonstra, por si, uma condição de superpopulação.","D":"A vocalização não funciona principalmente como orientação de insetos para captura.","E":"O canto dos machos pode atrair fêmeas e participar da comunicação reprodutiva."},"takeaway":"Separe o efeito incômodo de um comportamento para humanos de sua função biológica.","key":"natureza:N270","area":"natureza","year":2024,"number":117,"answer":"E","subject":"Biologia","topic":"Zoologia e parasitologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Menor pH favorece a desmineralização","steps":["A presença de H⁺ favorece a dissolução da hidroxiapatita no equilíbrio mostrado.","Entre os cremes, IV tem o menor pH, 6,9, portanto maior concentração de H⁺.","Ele promove a maior tendência relativa de desmineralização na comparação dada: D. Cálcio e fosfato também podem atuar como íons comuns nos demais casos."],"alternatives":{"A":"I tem pH 9,5, mais básico que IV e com menos H⁺.","B":"II tem o maior pH e contém cálcio, não oferece a maior tendência de dissolução.","C":"III tem pH 7,7, maior que 6,9; portanto apresenta menos H⁺ que IV.","D":"IV apresenta o menor pH entre as opções, favorecendo relativamente a reação de dissolução.","E":"V tem pH maior que IV e fornece componentes relacionados ao equilíbrio do mineral."},"takeaway":"Compare pH e íons comuns no modelo da questão, sem transformar o cálculo em recomendação clínica.","key":"natureza:N797","area":"natureza","year":2024,"number":118,"answer":"D","subject":"Química","topic":"Equilíbrio químico e pH","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Somar tempos com velocidades relativas","steps":["Nas travessias de 800 m, a componente horizontal útil é √(50² − 30²) = 40 m/min para compensar a corrente vertical.","Essas duas pernas levam 2 × 800/40 = 40 min. Nas pernas de 400 m, as velocidades são 50 + 30 = 80 e 50 − 30 = 20 m/min.","O tempo total é 40 + 400/80 + 400/20 = 65 min, B."],"alternatives":{"A":"42 min não incorpora corretamente as duas travessias e as pernas a favor e contra a corrente.","B":"65 min soma os tempos de 40, 5 e 20 minutos com as velocidades relativas corretas.","C":"72 min não corresponde à soma dos tempos calculados para os quatro trechos.","D":"105 min superestima a soma obtida com 40 m/min nas travessias e 80/20 nas laterais.","E":"120 min não é o tempo do circuito dado; a corrente não reduz todas as pernas à mesma velocidade."},"takeaway":"Para correnteza transversal, componha vetores; para correnteza paralela, some ou subtraia velocidades.","key":"natureza:N567","area":"natureza","year":2024,"number":119,"answer":"B","subject":"Física","topic":"Hidrostática e fluidos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Proliferação de linfócitos e câncer","steps":["O texto diferencia HTLV-1, que estimula produção de linfócitos, de HIV, que destrói essas células.","O aumento desregulado da proliferação pode contribuir para uma neoplasia.","A consequência possível é câncer, B; isso não significa que toda pessoa infectada terá câncer."],"alternatives":{"A":"A aids está associada à infecção por HIV, não é a consequência específica indicada para HTLV-1.","B":"A proliferação alterada de linfócitos pode relacionar-se a uma neoplasia.","C":"O trecho não descreve alteração de insulina ou de regulação da glicemia.","D":"Hepatite B tem outro agente e não decorre dessa proliferação de linfócitos.","E":"Hemorragia não é a consequência mais diretamente relacionada ao mecanismo destacado."},"takeaway":"Identifique o mecanismo específico do vírus; agentes com vias de transmissão semelhantes não causam a mesma doença.","key":"natureza:N292","area":"natureza","year":2024,"number":120,"answer":"B","subject":"Biologia","topic":"Microbiologia e imunologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Força de contato é normal mais atrito","steps":["Calvin chega ao chão com movimento para baixo e para a direita na tirinha.","O chão exerce normal para cima e uma componente de atrito contrária ao movimento horizontal.","A soma das forças exercidas pelo chão aponta para cima e para a esquerda: A. O peso é exercido pela Terra e não integra a força pedida."],"alternatives":{"A":"O vetor combina a componente vertical da normal com a horizontal contrária ao deslizamento.","B":"O sentido para a direita reforçaria o movimento horizontal e omite a normal.","C":"O vetor só para a esquerda inclui atrito, mas omite a componente normal para cima.","D":"O vetor vertical omite a componente de contato que se opõe ao movimento horizontal.","E":"O vetor para cima e direita tem componente horizontal no sentido incorreto."},"takeaway":"Diferencie resultante de todas as forças da resultante exercida por um agente específico.","key":"natureza:N377","area":"natureza","year":2024,"number":121,"answer":"A","subject":"Física","topic":"Mecânica: cinemática e dinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Dentro do iglu não precisa estar abaixo de zero","steps":["A neve isola termicamente e reduz a perda de calor do interior.","O calor dos ocupantes pode manter o ambiente interno acima da temperatura de solidificação da água.","Nesse caso, a geladeira retira calor para formar gelo: A, mesmo que fora esteja muito frio."],"alternatives":{"A":"Se o interior está acima de 0 °C nas condições usuais, a água precisa de refrigeração para congelar.","B":"Umidade não é a condição principal que impede a solidificação na cena.","C":"Isolamento reduz trocas térmicas, mas o fator decisivo é a temperatura interna acima da de congelamento.","D":"Não haver convecção não impediria, por si só, uma mudança de fase.","E":"Não há indicação de pressão interna baixa capaz de explicar o fenômeno."},"takeaway":"Um isolante não produz frio nem calor: ele reduz a taxa de transferência de energia.","key":"natureza:N497","area":"natureza","year":2024,"number":122,"answer":"A","subject":"Física","topic":"Termologia e termodinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A carbonila e a hidroxila devem ser lidas juntas","steps":["Os dois compostos contêm o grupo –C(=O)OH.","Carbonila e OH ligados ao mesmo carbono formam carboxila, identificando ácido carboxílico.","A função comum é A; não se deve classificar o OH da carboxila isoladamente como álcool ou fenol."],"alternatives":{"A":"A carboxila aparece nas duas estruturas e caracteriza a função comum.","B":"A cetona aparece no composto 2, mas não é a função compartilhada com o 1.","C":"Uma ligação dupla do composto 2 não define uma função comum às duas moléculas.","D":"O OH da carboxila não constitui uma função álcool independente.","E":"O OH ligado ao anel aromático caracteriza fenol no composto 1, não nos dois."},"takeaway":"Leia grupos funcionais completos: a mesma letra O pode participar de funções químicas diferentes.","key":"natureza:N674","area":"natureza","year":2024,"number":123,"answer":"A","subject":"Química","topic":"Química orgânica: funções e propriedades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A distribuição mostra a dependência de oxigênio","steps":["No tubo 1, as bactérias se concentram na superfície, mais rica em O₂.","No tubo 2, ocupam a região inferior; no 3, distribuem-se ao longo do meio, com crescimento também onde há oxigênio.","São aeróbios estritos, anaeróbios estritos e anaeróbios facultativos, respectivamente: C."],"alternatives":{"A":"O tubo 1 não mostra a distribuição ampla esperada para facultativos.","B":"Troca os metabolismos dos tubos 1 e 3, apesar de suas distribuições diferentes.","C":"A alternativa respeita a concentração superficial, inferior e distribuída nos três tubos.","D":"Inverte os dois primeiros tubos, confundindo preferência e intolerância ao oxigênio.","E":"Troca os tubos 2 e 3: só o terceiro mostra crescimento com e sem oxigênio."},"takeaway":"Relacione posição no tubo ao gradiente de O₂, não à quantidade total aparente de bactérias.","key":"natureza:N293","area":"natureza","year":2024,"number":124,"answer":"C","subject":"Biologia","topic":"Microbiologia e imunologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Emitir luz envolve estados eletrônicos","steps":["A placa absorve energia luminosa e pode continuar emitindo após a exposição.","A emissão ocorre em transições de estados eletrônicos de maior para menor energia.","C explica a fosforescência; a persistência do brilho não exige reflexão contínua nem alteração nuclear."],"alternatives":{"A":"Colisões podem participar de trocas de energia, mas não identificam o mecanismo luminoso pedido.","B":"Coloração dos átomos não é uma explicação física das emissões discretas de energia.","C":"A relaxação eletrônica pode liberar fótons, produzindo a luz observada.","D":"O processo não envolve transformação de núcleos atômicos.","E":"Reflexão exige luz incidente e não explica a emissão persistente no escuro."},"takeaway":"Diferencie luminescência, reflexão e processos nucleares; emissão luminosa pode ocorrer sem aquecimento intenso.","key":"natureza:N854","area":"natureza","year":2024,"number":125,"answer":"C","subject":"Química","topic":"Estrutura atômica e periodicidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O condutor deve blindar sua cavidade","steps":["Em equilíbrio eletrostático, o campo no material condutor é nulo e, sem cargas na cavidade, também é nulo nela.","As linhas externas se deformam e encontram a superfície condutora perpendicularmente.","E respeita a blindagem e o sentido do campo da barra positiva A para a negativa B."],"alternatives":{"A":"As linhas atravessam a cavidade como se o cilindro não produzisse blindagem.","B":"Além de atravessar a região interna, mostra sentido incompatível com as barras.","C":"O esquema apresenta sentido inadequado e campo na região que deveria estar blindada.","D":"A deformação externa não basta: há linhas atravessando o interior.","E":"O campo contorna o cilindro, não atravessa a cavidade e mantém o sentido positivo para negativo."},"takeaway":"Blindagem eletrostática não significa apagar o campo externo: ele se reorganiza ao redor do condutor.","key":"natureza:N325","area":"natureza","year":2024,"number":127,"answer":"E","subject":"Física","topic":"Eletricidade e circuitos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Separação de cargas produz tensão","steps":["O grafeno possui elétrons capazes de se deslocar ao longo da superfície.","A interação com os cátions da água favorece uma distribuição de cargas e uma diferença de potencial.","E descreve esse mecanismo; o texto não apresenta o grafeno como reagente que oxida cátions nem como catalisador."],"alternatives":{"A":"Não se descreve retirada de elétrons dos cátions por oxidação.","B":"Impedir a difusão da água não explica a geração elétrica relatada.","C":"O texto não afirma redução de energia de ativação por catálise.","D":"Não se indica produção de um compósito como o mecanismo gerador.","E":"A interação entre portadores de carga e cátions permite estabelecer diferença de potencial."},"takeaway":"Diferencie processos eletrostáticos de separação de cargas de reações de oxirredução.","key":"natureza:N326","area":"natureza","year":2024,"number":128,"answer":"E","subject":"Física","topic":"Eletricidade e circuitos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Questão anulada: os dados da cafeteira","steps":["O gabarito oficial anula o item; nenhuma letra deve ser restaurada.","Com os números apresentados, Q = 500 × 4,2 × (100 − 20) = 168 000 J. Em 3 min, a entrada seria 700 × 180 = 126 000 J.","A razão usual Q/E seria aproximadamente 133%, incompatível com o modelo sem outra fonte de energia. O tempo ideal seria 240 s. Esta análise dos dados não atribui um motivo oficial à anulação."],"alternatives":{"A":"100% seria o caso ideal compatível com 240 s, não com a entrada informada em 180 s.","B":"75% corresponde à razão invertida 126 000/168 000, não ao rendimento útil/fornecido usual.","C":"60% não resulta da razão entre calor necessário e energia elétrica com os dados apresentados.","D":"7,5% não representa a relação energética calculada em unidades consistentes.","E":"5,1% também não corresponde à razão física usual; a situação oficial continua anulada."},"takeaway":"Cheque plausibilidade: eficiência acima de 100% exige rever dados ou modelo, nunca inventar uma letra.","key":"natureza:N498","area":"natureza","year":2024,"number":129,"answer":"Anulada","subject":"Física","topic":"Termologia e termodinâmica","status":"verified","annulled":true,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A expansão entrega trabalho útil","steps":["Na etapa IV, o gás se expande adiabaticamente e desloca o pistão.","O trabalho feito pelo gás é positivo; sem receber calor nessa etapa, sua energia interna diminui.","É nessa expansão que a energia do fluido se converte em trabalho útil, alternativa C."],"alternatives":{"A":"II é compressão: o trabalho é realizado sobre o gás, não é a expansão útil.","B":"III introduz calor a volume constante no modelo; não há trabalho de expansão nessa etapa.","C":"IV corresponde à expansão adiabática que realiza trabalho sobre o pistão.","D":"V libera calor a volume constante, não é a etapa útil de expansão.","E":"VI trata da saída dos gases, não da conversão principal destacada."},"takeaway":"Num diagrama P–V, trabalho envolve variação de volume; aquecer não significa necessariamente realizar trabalho.","key":"natureza:N499","area":"natureza","year":2024,"number":130,"answer":"C","subject":"Física","topic":"Termologia e termodinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Um resistor para cada LED em paralelo","steps":["Cada LED precisa de 3,0 V e 1,0 mA; restam 4,5 − 3,0 = 1,5 V no resistor.","R = 1,5 V/0,001 A = 1 500 Ω para cada ramo.","B coloca um resistor e um LED corretamente polarizado em cada ramo paralelo, acendendo ambos na corrente máxima."],"alternatives":{"A":"Um resistor comum limita a corrente total a 1 mA, que se divide entre os LEDs; não fornece 1 mA a cada um.","B":"Cada ramo tem queda de 1,5 V no resistor de 1,5 kΩ, resultando em 1 mA no LED.","C":"Os LEDs estão polarizados no sentido que não permite a corrente necessária.","D":"Dois LEDs em série exigem pelo menos 6 V, acima dos 4,5 V disponíveis.","E":"Os LEDs também estão no sentido bloqueado; o resistor comum não corrige a polarização."},"takeaway":"Verifique simultaneamente polaridade, tensão de funcionamento e limite de corrente de cada ramo.","key":"natureza:N327","area":"natureza","year":2024,"number":131,"answer":"B","subject":"Física","topic":"Eletricidade e circuitos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Igualar o potencial no ponto intermediário","steps":["As correntes nominais são 9/6 = 1,5 A e 18/12 = 1,5 A; em série, as duas lâmpadas podem operar juntas com 18 V.","O ponto P deve ficar a 6 V de Q, ou seja, a um terço da tensão total do fio uniforme.","Um terço de 48 cm é 16 cm, o ponto B. Nesse equilíbrio, ligar o amperímetro não desvia corrente entre os pontos de mesmo potencial."],"alternatives":{"A":"A corresponde a um sexto do fio e a 3 V, não aos 6 V exigidos entre Q e P.","B":"B corresponde a dois sextos do fio, com divisão de 6 V e 12 V.","C":"C divide o fio ao meio, gerando 9 V de cada lado, diferente dos valores nominais.","D":"D corresponde a 12 V desde Q, invertendo a proporção necessária.","E":"E corresponde a 15 V desde Q, deixando apenas 3 V no outro segmento."},"takeaway":"Em uma ponte equilibrada, pontos de mesmo potencial podem ser ligados sem corrente pelo ramo transversal.","key":"natureza:N328","area":"natureza","year":2024,"number":132,"answer":"B","subject":"Física","topic":"Eletricidade e circuitos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Usar a equivalência energética do enunciado","steps":["Dez mol de etanol têm massa 460 g e volume 460/0,78 ≈ 590 mL = 0,59 L.","Essa quantidade é substituída por cerca de 1 m³ de biogás, dos quais 70% são CH₄: 700 L.","A massa de metano é (700/22) × 16 ≈ 509 g, próxima de 510 g, C."],"alternatives":{"A":"300 g não corresponde aos 700 L de metano nas condições do volume molar dado.","B":"400 g subestima a massa obtida por volume molar e massa molar.","C":"510 g aproxima o resultado ao aplicar composição e equivalência energética fornecidas.","D":"590 é aproximadamente o volume de etanol em mL, não a massa de metano.","E":"720 g não corresponde à conversão de 700 L com 22 L/mol e 16 g/mol."},"takeaway":"Não substitua mol de combustível por mol de outro: use a equivalência energética explicitamente fornecida.","key":"natureza:N721","area":"natureza","year":2024,"number":133,"answer":"C","subject":"Química","topic":"Estequiometria e gases","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Retirar o metal exige remover a biomassa","steps":["Mercúrio é elemento químico: não pode ser destruído por uma enzima como uma molécula orgânica.","Na fitoextração, as plantas acumulam o metal e são colhidas para retirar a biomassa contaminada da área.","E atende à remoção e ao controle da entrada na cadeia alimentar, desde que haja destinação adequada dessa biomassa."],"alternatives":{"A":"Estabilizar imobiliza o contaminante no local, mas não o retira da área.","B":"Volatilizar transfere o mercúrio à atmosfera e não assegura o controle solicitado.","C":"Não há degradação biológica de um elemento químico que o faça deixar de ser mercúrio.","D":"Imobilização por microrganismos não corresponde à retirada da biomassa que remove o metal.","E":"Acumular e colher as plantas permite retirar o contaminante com manejo adequado."},"takeaway":"Remover, imobilizar e transferir de compartimento não são sinônimos de descontaminar com segurança.","key":"natureza:N009","area":"natureza","year":2024,"number":134,"answer":"E","subject":"Biologia","topic":"Ecologia e impactos ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Reciclagem evita extração em proporção maior","steps":["A massa reciclada é 0,974 × 4,0 × 10⁵ = 3,896 × 10⁵ toneladas de alumínio.","A produção primária exige 50/10 = 5 toneladas de bauxita para cada tonelada de alumínio.","A extração evitada é 5 × 3,896 × 10⁵ = 1,948 × 10⁶ t, aproximadamente 1,9 × 10⁶ t, D."],"alternatives":{"A":"10⁴ toneladas está muito abaixo da própria massa reciclada e da razão minério/metal.","B":"3,9 × 10⁵ t aproxima o alumínio reciclado, sem converter para bauxita.","C":"5,0 × 10⁵ t não aplica corretamente o índice de reciclagem e a razão de cinco para um.","D":"A alternativa aproxima o produto da massa reciclada pelo fator cinco.","E":"2,0 × 10⁷ t acrescenta uma ordem de grandeza indevida ao resultado."},"takeaway":"A porcentagem incide sobre as latas; a razão de produção converte a massa de alumínio em minério evitado.","key":"natureza:N765","area":"natureza","year":2024,"number":135,"answer":"D","subject":"Química","topic":"Eletroquímica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"natureza/gab_2024.pdf","sha256":"8d27b5a447061e9a1c181d00a916d10f45e1c6c1da68d628b3ae8bdfedbf5c92","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2024.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
